/// Optional: only supported since gcc >= 15, clang >= 19
///
///   gcc: https://gcc.gnu.org/onlinedocs/gcc/Other-Builtins.html#index-_005f_005fbuiltin_005fcounted_005fby_005fref
/// clang: https://clang.llvm.org/docs/LanguageExtensions.html#builtin-counted-by-ref
#[inline(always)]
fn __inline_bsearch(key: *const (), mut base: *const (), mut num: u64, size: u64, cmp: Option<unsafe extern "C" fn(*const (), *const ()) -> i32>) -> *mut () {
let mut result: i32 = 0;
while num > 0 {
let pivot: *const u8 = ((unsafe { (base as *const u8).wrapping_offset((num >> 1i32).wrapping_mul(size) as isize) }) as *const ()) as *const u8;
result = unsafe { cmp.unwrap()(key, pivot as *const ()) };
if result == 0 {
return pivot as *mut ();
}
if result > 0 {
base = pivot.wrapping_offset(size as isize) as *const ();
num = num.wrapping_sub(1);
}
num >>= 1i32;
}
core::ptr::null_mut::<()>()
}

